// MARK: - 项目记录模型
@Model
final class SDProjectRecord {
    var id: UUID = UUID()
    var name: String = ""
    var date: Date = Date()
    var totalBeads: Int = 0
    var brandId: UUID?
    var isArchived: Bool = false
    var parentId: UUID?           // 父项目ID，nil表示顶级项目
    var isPlanned: Bool?          // 是否为计划项目（可选，nil视为false）
    var executedDate: Date?       // 执行日期
    // 关于这四个大 blob 字段为什么暂时**不**加 @Attribute(.externalStorage)：
    //
    // 单条可达 MB 级。理想形态是走 externalStorage 让 blob 落成 .store_blob 旁路文件，但
    // SwiftData 的 lightweight migration **不支持**「现存 inline BLOB → external file reference」
    // 自动迁移（已验证：会抛 "Unable to use inferred mapping to move external reference into
    // store"，ModelContainer 初始化失败 → 全员升级即崩 → 退回本地模式丢 iCloud 同步）。
    // 真正引发 458 项目用户 jetsam 的根因是 InventoryManager.projects 缓存把全部
    // ProjectRecord 含 Data 物化进内存 + 列表 row 解码原图 PNG 撑爆内存，本 PR 通过
    //   1. toMetadataStruct() 让 projects 缓存只携带 metadata（不读 4 个 blob）
    //   2. displayThumbnail 字段（512px JPEG 0.85，列表 row 专用 ~50-100 KB）
    //   3. ThumbnailMigrationCoordinator 给老数据 backfill displayThumbnail
    //   4. ProjectThumbnailImage 列表优先读 displayThumbnail，没有就 CGImageSource 现场降级（永不 UIImage(data: raw_thumbnail)）
    // 一并解决。externalStorage 留作未来 PR 配合 VersionedSchema + 显式 willMigrate/didMigrate 手工搬迁。
    var thumbnail: Data?          // 「原图」—— 全分辨率 PNG（拼图模式 / 详情大图用）。字段名保留为 thumbnail
                                  // 是为了避免 SwiftData schema 迁移（CloudKit container 对字段重命名很敏感）。
    var finishedImage: Data?      // 成品图数据（PNG，仅已执行项目使用）
    var completedDate: Date?      // 完成日期（用于日历展示）
    var colorSystemRaw: String?   // 色号体系，可选以兼容旧数据，默认为 MARD
    var patternGridData: Data?    // JSON 编码后的 BeadPatternGrid（拼图模式网格数据）
    var displayThumbnail: Data?   // 列表用小图（CGImageSourceCreateThumbnailAtIndex 出 512px JPEG 0.85）。
                                  // 老数据 nil，由 ThumbnailMigrationCoordinator 后台 backfill；视图层在
                                  // 它还是 nil 时降级用 ImageDownsampler.downsampleToUIImage(thumbnail) 现场降级。

    @Relationship(deleteRule: .cascade, inverse: \SDBeadUsage.project)
    var beadUsages: [SDBeadUsage]? = []

    // 计算属性：安全获取 isPlanned 值
    var isPlannedValue: Bool {
        isPlanned ?? false
    }

    init(id: UUID = UUID(), name: String, date: Date = Date(), totalBeads: Int = 0, brandId: UUID? = nil, isArchived: Bool = false, parentId: UUID? = nil, isPlanned: Bool = false, executedDate: Date? = nil, thumbnail: Data? = nil, finishedImage: Data? = nil, completedDate: Date? = nil, colorSystemRaw: String? = nil, patternGridData: Data? = nil, displayThumbnail: Data? = nil, beadUsages: [SDBeadUsage] = []) {
        self.id = id
        self.name = name
        self.date = date
        self.totalBeads = totalBeads
        self.brandId = brandId
        self.isArchived = isArchived
        self.parentId = parentId
        self.isPlanned = isPlanned
        self.executedDate = executedDate
        self.thumbnail = thumbnail
        self.finishedImage = finishedImage
        self.completedDate = completedDate
        self.colorSystemRaw = colorSystemRaw
        self.patternGridData = patternGridData
        self.displayThumbnail = displayThumbnail
        self.beadUsages = beadUsages
    }

    convenience init(from record: ProjectRecord) {
        let usages = record.beadUsage.map { SDBeadUsage(from: $0) }
        let gridData = SDProjectRecord.encodePatternGrid(record.patternGrid, projectId: record.id)
        self.init(id: record.id, name: record.name, date: record.date, totalBeads: record.totalBeads, brandId: record.brandId, isArchived: record.isArchived, parentId: record.parentId, isPlanned: record.isPlanned, executedDate: record.executedDate, thumbnail: record.thumbnail, finishedImage: record.finishedImage, completedDate: record.completedDate, colorSystemRaw: record.colorSystem.rawValue, patternGridData: gridData, displayThumbnail: record.displayThumbnail, beadUsages: usages)
    }

    /// 完整版转换：读取 thumbnail / finishedImage / patternGridData / displayThumbnail 四个大 blob 字段。
    /// 仅用于一次性需要全数据的路径（备份导出、详情页全屏图、history 快照前快照存档等）。
    /// **不要**在 InventoryManager.projects 这种全表缓存里调用 —— 用 toMetadataStruct()。
    func toStruct() -> ProjectRecord {
        let usages = (beadUsages ?? []).map { $0.toStruct() }
        let grid = SDProjectRecord.decodePatternGrid(patternGridData, projectId: id)
        return ProjectRecord(
            id: id,
            name: name,
            date: date,
            beadUsage: usages,
            totalBeads: totalBeads,
            brandId: brandId,
            isArchived: isArchived,
            parentId: parentId,
            isPlanned: isPlannedValue,
            executedDate: executedDate,
            thumbnail: thumbnail,
            finishedImage: finishedImage,
            completedDate: completedDate,
            colorSystem: ColorSystem(rawValue: colorSystemRaw ?? "") ?? .mard,
            patternGrid: grid,
            displayThumbnail: displayThumbnail
        )
    }

    /// 轻量版转换：metadata + beadUsages，但**不读** 4 个 blob 字段
    /// （thumbnail / finishedImage / patternGridData / displayThumbnail）。
    /// 用于 InventoryManager.projects 全表缓存 —— 458 项目时把内存峰值从 ~200MB 砍到 ~MB 级。
    /// 视图需要图片时走 InventoryManager.fetchProject*Data / fetchProjectDisplayThumbnail 按需取。
    /// 注意：调用方在 saveData 路径上必须用对应的轻量 diff，避免把 nil blob 写回覆盖云端真数据。
    func toMetadataStruct() -> ProjectRecord {
        let usages = (beadUsages ?? []).map { $0.toStruct() }
        return ProjectRecord(
            id: id,
            name: name,
            date: date,
            beadUsage: usages,
            totalBeads: totalBeads,
            brandId: brandId,
            isArchived: isArchived,
            parentId: parentId,
            isPlanned: isPlannedValue,
            executedDate: executedDate,
            thumbnail: nil,
            finishedImage: nil,
            completedDate: completedDate,
            colorSystem: ColorSystem(rawValue: colorSystemRaw ?? "") ?? .mard,
            patternGrid: nil,
            displayThumbnail: nil
        )
    }

    /// 把 BeadPatternGrid 编码成持久化用的 JSON Data。失败时返回 nil 并记日志，
    /// 调用方应自行判断是否覆盖已有数据（iCloud 同步路径应保留 last-known-good）。
    static func encodePatternGrid(_ grid: BeadPatternGrid?, projectId: UUID) -> Data? {
        guard let grid else { return nil }
        do {
            return try JSONEncoder().encode(grid)
        } catch {
            AppLogger.shared.error(
                "SDProjectRecord",
                "patternGrid_encode_failed",
                metadata: [
                    "projectId": projectId.uuidString,
                    "error": "\(error)"
                ]
            )
            return nil

//
//  ImageDownsampler.swift
//  BeadInventory
//
//  原图 → 小缩略图的 downsample 工具。供 displayThumbnail 字段生成 + 列表 row
//  在 displayThumbnail 缺失时的 fallback 解码使用。
//
//  设计要点：
//  - 用 ImageIO `CGImageSourceCreateThumbnailAtIndex` 而不是 UIImage(data:) + resize：
//    前者在 CGImageSource 内部直接生成目标尺寸位图，跳过全分辨率解码 → 内存峰值 KB 级
//    而不是 MB 级；后者会把原图先解码出来（30+ MB），背道而驰。
//  - `kCGImageSourceCreateThumbnailFromImageAlways = true` 强制生成（即使源图无 EXIF
//    thumbnail），`shouldCacheImmediately = true` 把解码挪到这里完成（而不是后续 draw time
//    在主线程上发生）。
//  - 输出 JPEG @ 0.85：经验值 —— 拼豆图大多色块密集，JPEG 0.85 几乎看不出退化，
//    单图通常 30-100 KB（vs 原 PNG 几 MB）。0.9 大小翻倍，0.8 开始能看到色块边缘 artifact。
//  - 标记 `nonisolated` —— 调用方可以从任意 Task / 后台 actor 调用，不必跳主线程。
//
//  错误处理：失败时返回 nil + logError 一条诊断。调用方需要兜底 ——
//  **写入 displayThumbnail = nil**（清空），让 `ProjectThumbnailImage` 走第二优先级
//  fallback（CGImageSourceCreateThumbnailAtIndex 实时 downsample）兜底。
//  Round-4 曾把"用原 thumbnail 字节兜底"，但那会让列表 row 通过 `UIImage(data:)` 解码 5-10 MB
//  PNG 重蹈 jetsam —— round-5 F1 改回 nil。

import Foundation
import UIKit
import ImageIO

enum ImageDownsampler {

    /// downsample 输出目标：512px 以内的最大边 + JPEG 0.85。
    /// 数字经过测算：列表 row 在 3x 设备上不超过 120pt，512px 已经远超显示需求 + 留出
    /// 用户从列表点开后的瞬间放大缓冲。再大就接近原图，没有压缩意义。
    static let defaultMaxPixelSize: Int = 512
    static let defaultJPEGQuality: CGFloat = 0.85

    /// 把 PNG / JPEG 原图字节降采样成小缩略图。
    ///
    /// - Parameters:
    ///   - sourceData: 原图字节（PNG/JPEG，任意尺寸）
    ///   - maxPixelSize: 输出最大边长（默认 512px）
    ///   - jpegQuality: JPEG 输出质量（默认 0.85）
    /// - Returns: JPEG 字节；失败返回 nil（不抛 throw，避免把"用户图坏了/格式特别"误升级成错误流）
    static nonisolated func downsample(
        _ sourceData: Data,
        maxPixelSize: Int = defaultMaxPixelSize,
        jpegQuality: CGFloat = defaultJPEGQuality
    ) -> Data? {
        // 用 ImageIO 不走 UIImage —— UIImage(data:) 会先解码全分辨率，内存峰值会到原图
        // RGBA × pixel 数（5MB PNG → ~30MB UIImage）。CGImageSource 直接出小图，峰值 KB 级。
        let sourceOptions: [CFString: Any] = [
            kCGImageSourceShouldCache: false  // 不缓存源图全分辨率
        ]
        guard let source = CGImageSourceCreateWithData(sourceData as CFData, sourceOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_source_failed", metadata: [
                "bytes": sourceData.count
            ])
            return nil
        }

        let thumbnailOptions: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,  // 应用 EXIF 方向
            kCGImageSourceShouldCacheImmediately: true,         // 解码在这里完成
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ]
        guard let cgThumb = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_thumbnail_failed", metadata: [
                "bytes": sourceData.count,
                "maxPixelSize": maxPixelSize
            ])
            return nil
        }

        let uiThumb = UIImage(cgImage: cgThumb)
        guard let jpeg = uiThumb.jpegData(compressionQuality: jpegQuality) else {
            AppLogger.shared.error("ImageDownsampler", "jpeg_encode_failed", metadata: [
                "bytes": sourceData.count,
                "thumbWidth": cgThumb.width,
                "thumbHeight": cgThumb.height
            ])
            return nil
        }
        return jpeg
    }

    /// 跟 downsample 一样，但返回 UIImage 而不是字节 —— 给「列表 row 没有 displayThumbnail
    /// 时直接用 fallback 显示」的路径用，省一次 JPEG encode + decode round-trip。
    ///
    /// 注意：返回的 UIImage 已经预解码（kCGImageSourceShouldCacheImmediately），
    /// 上屏不会再触发主线程 decode。
    static nonisolated func downsampleToUIImage(
        _ sourceData: Data,
        maxPixelSize: Int = defaultMaxPixelSize
    ) -> UIImage? {
        let sourceOptions: [CFString: Any] = [
            kCGImageSourceShouldCache: false
        ]
        guard let source = CGImageSourceCreateWithData(sourceData as CFData, sourceOptions as CFDictionary) else {
            // **round-10 review Nit**：之前两个失败点都静默返 nil，跟兄弟 method `downsample`
            // 不对称。这条路径是老用户没有 displayThumbnail 时列表 row 的兜底降级 ——
            // 如果某些畸形 PNG / 损坏字节让 CGImageSource 创建失败，用户看到列表里那个 row
            // 永远是 placeholder，Sentry 抓不到 → 调查无从下手。补 logError 让监控可观测。
            AppLogger.shared.error("ImageDownsampler", "create_source_failed_uimage_path", metadata: [
                "sourceBytes": sourceData.count
            ])
            return nil
        }
        let thumbnailOptions: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ]
        guard let cgThumb = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_thumbnail_failed_uimage_path", metadata: [
                "sourceBytes": sourceData.count,
                "maxPixelSize": maxPixelSize
            ])
            return nil
        }
        return UIImage(cgImage: cgThumb)
    }

    // 注：原先有 `migrationThresholdBytes = 200_000` —— round-5 N1 后已弃用
    //（一张 199 KB 的 4000×4000 PNG 仍能 UIImage(data:) 解码爆 60MB，所以 migration 不能因
    // "字节小"就跳过 downsample）。常量已删除，避免给未来维护者错误信号。
}

