// MARK: - 测试探针

/// 供 `ProjectImageLoaderTests` 钉住「取图不在主线程」这条不变量。
/// 一旦有人把本类改回 `@MainActor`（或把 fetch 挪回 `InventoryManager`），测试会红。
func isCurrentlyOnMainThreadForTesting() -> Bool { Thread.isMainThread }

/// 观测到的最大并发数。actor 隔离下恒为 1 —— 老数据兜底路径靠它保证
